class PriceStreak {
    private final List<Integer> days = new ArrayList<>();

    public PriceStreak() {
    }

    public int record(int price) {
        days.add(price);
        int streak = 0;
        for (int i = days.size() - 1; i >= 0; i--) {
            if (days.get(i) > price) break;
            streak++;
        }
        return streak;
    }
}

