class PriceStreak {
    private final Deque<int[]> stack = new ArrayDeque<>();

    public PriceStreak() {
    }

    public int record(int price) {
        int streak = 1;
        while (!stack.isEmpty() && stack.peek()[0] <= price) streak += stack.pop()[1];
        stack.push(new int[] {price, streak});
        return streak;
    }
}

